    reasons.push("independent spendable-capacity verification is not provisioned");
    if (ctx2.env !== "mainnet-enabled" || !ctx2.caps.canSubmitTransactions || !ctx2.cfg.pilot.livePayoutsEnabled) reasons.push("live money movement disabled");
    if (!ctx2.cfg.approvals.legal || !ctx2.cfg.approvals.provider) reasons.push("legal/provider approval missing");
    if (BigInt(c.requested_inr_paise) > ctx2.cfg.pilot.maxPayoutInrPaise) reasons.push("per-order cap exceeded");
    const daily = await one(t, `SELECT coalesce(sum(max_usdc_debit_micros),0) AS total FROM payout_commands WHERE environment=$1 AND created_at > now()-interval '1 day' AND state NOT IN ('PREFLIGHT_BLOCKED','EXPIRED','USER_ABORTED','REFUNDED')`, [ctx2.env]);
