    const bad = await maybeOne(t, `SELECT 1 FROM deposit_observations WHERE intent_id=$1 AND accepted AND (NOT canonical OR NOT mined OR confirmations<$2)`, [id, ctx2.cfg.policy.requiredConfirmations]);
