  const checks = [];
  const add = (name, ok2, detail, blocked = false) => checks.push({ name, ok: ok2, status: blocked ? "BLOCKED" : ok2 ? "PASS" : "FAIL", detail });
  const unbalanced = await findUnbalancedJournals(ctx2.db, env);
